def build(rows: list, difficulty: str) -> list[dict]:
    out = []
    for q, choices, answer, explanation, tags in rows:
        out.append({
            **B,
            "difficulty": difficulty,
            "question": q,
            "choices": choices,
            "answer": answer,
            "explanation": explanation,
            "tags": tags,
        })
    return out


def main() -> None:
    questions = build(EASY[:200], "Easy") + build(MEDIUM[:200], "Medium") + build(HARD[:200], "Hard")
    for i, q in enumerate(questions, 1):
        q["id"] = i

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(questions, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Wrote {len(questions)} questions to {OUTPUT}")
    print(f"  Easy: {min(len(EASY), 200)}, Medium: {min(len(MEDIUM), 200)}, Hard: {min(len(HARD), 200)}")


if __name__ == "__main__":
    main()
